"""Render the completed upstream-screen comparison independently of the ongoing protein/NR experiment."""
import datetime,hashlib,html,json,subprocess
from pathlib import Path
r=Path(__file__).resolve().parent
if not (r/'results').exists():raise SystemExit('Run the reporting copy beside the collected results directory')
paths={name:r/'results'/name for name in ['heldout/summary.json','heldout/resource-summary.json','heldout/species-summary.json','heldout/support-transitions.json','aa-over-nt20-final1000/mechanism-summary.json','preparation-discrepancies/header-control-summary.json','preparation-discrepancies/header-control-protocol.json']}
data={name:json.loads(p.read_text()) for name,p in paths.items()};s=data['heldout/summary.json'];cpu=data['heldout/resource-summary.json']['arms'];species=data['heldout/species-summary.json']['counts'];trans=data['heldout/support-transitions.json']['counts'];headers=data['preparation-discrepancies/header-control-summary.json'];baseline=s['arms']['nt']['totals']['final_pairs'];ratio=(cpu['union']['screen_CPU_seconds']['total']+cpu['union']['downstream_CPU_seconds_estimate']['total'])/(cpu['nt20']['screen_CPU_seconds']['total']+cpu['nt20']['downstream_CPU_seconds_estimate']['total'])
assert s['completed_samples']==1000 and s['sampled_input_pairs']==5000000000
style='<style>body{max-width:1060px;margin:48px auto;padding:0 28px;font:17px/1.55 system-ui;color:#17212c}h1{line-height:1.15}h2{margin-top:36px}table{border-collapse:collapse;width:100%;font-size:15px;margin:20px 0}td,th{border-bottom:1px solid #cbd5df;padding:9px;text-align:right}td:first-child,th:first-child{text-align:left}code{font-size:13px;overflow-wrap:anywhere}p.note{color:#48596b;font-size:15px}</style>'
def page(title,body):return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title>'+style+'<body><p><strong>Codex says:</strong> Experimental results, October 22, 2026.</p><h1>'+title+'</h1>'+body+'</body></html>'
def table(labels,rows):return '<table><thead><tr>'+''.join('<th>'+html.escape(str(x))+'</th>' for x in labels)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'
labels={'nt':'NT24 baseline','nt22':'NT22 screen','nt20':'NT20 screen','aa12':'AA12 replacement','union':'NT24 + AA12 union'}
rows=[]
for arm in labels:
 a=s['arms'][arm]['totals'];c=cpu[arm];rows.append([labels[arm],f"{a['final_pairs']:,}",f"{a['added_pairs']:,}",f"{a['lost_pairs']:,}",f"{c['screen_CPU_seconds']['total']:,.0f}",f"{c['downstream_CPU_seconds_estimate']['total']:,.0f}"])
body=f'<p>The first-step experiment is complete: 1,000 frozen public CASPER samples, five million read pairs per sample, five billion input pairs total. It changes the initial sequence screen and then runs the same downstream nucleotide pipeline. It is a reduced-depth cohort experiment, not a full-depth run of the public archive.</p><p>The NT24 + AA12 union retained <strong>19,637 additional final pairs ({100*19637/baseline:.3f}%)</strong> and lost none of the 1,478,260 baseline pairs. NT20 recovered 19,593 of those additions, missing 44, and retained another 474 pairs absent from the union. AA12 used as a replacement added 19,637 pairs but lost 2,673 baseline pairs.</p>'
body+='<h2>Read counts and measured CPU work</h2>'+table(['Screen','Final pairs','Added vs NT24','Lost vs NT24','Screen CPU s','Downstream CPU s (estimated)'],rows)
body+=f'<p>Screening plus downstream processing used {ratio:.2f} times as much CPU for the union as for NT20. This ratio combines native GNU time measurements for screening with Nextflow CPU estimates downstream. It excludes input extraction, index construction, union construction, reference staging, orchestration and idle workers. It is not a cloud-billing ratio or an isolated wall-time benchmark.</p><p>No shared retained read changed its assigned taxid across these screen variants.</p>'
rows=[]
for arm in ['nt22','nt20','aa12','union']:
 c=species[arm+'/minimum_3'];tr=trans[arm+'/all_species'];human=trans[arm+'/human_annotated'];rows.append([labels[arm],c['gained_sample_species_calls'],c['lost_sample_species_calls'],tr.get('baseline_support_0',0),c['gained_human_species_calls'],human.get('baseline_support_0',0)])
body+='<h2>Sample/species support at three exemplars</h2>'+table(['Screen','Gained calls','Lost calls','Gains with zero baseline support','Human-annotated gains','Human-annotated gains with zero baseline support'],rows)
body+='<p>The union adds 203 sample/species threshold crossings. Eight had zero baseline support; 29 previously had one exemplar and 166 had two. Among species annotated as human-infecting, the union adds 64 threshold crossings: five from one baseline exemplar and 59 from two, with none from zero. Thus “zero new species-level calls” is not a valid description of the full result.</p><p>These are the original pipeline’s species-rank clade counts after its duplicate handling. Three exemplars is a descriptive support threshold. These changes do not establish additional infections, biological truth, or prospective sensitivity. Human-infection annotations are properties of the reference species, not diagnoses of the samples.</p>'
body+='<h2>Why changing only the first screen has limited effect</h2><p>The downstream viral alignment still runs Bowtie2 with <code>--local --very-sensitive-local --score-min G,0.1,19 -k 10 -X 850</code>. Its multiseed preset uses zero mismatches in 20-nucleotide seeds. Translation in the first screen therefore does not remove the later nucleotide alignment constraint. This is a mechanism explaining the observed overlap, not a claim that every Bowtie2 alignment must follow exactly one seed path. <a href="https://bowtie-bio.sourceforge.net/bowtie2/manual.shtml#preset-options-in---local-mode">Bowtie2 documentation</a>.</p><p>All 44 union additions absent from raw NT20 screening were audited. Thirteen acquired an exact 20-nucleotide screening match after FASTP processing. The other 31 had such a match in the assigned DUST-filtered reference but not in the human-masked screening reference. Input processing and reference masking therefore explain the observed exceptions without establishing their biological correctness.</p><p>Translated validation against core_nt answers a later question: how previously detected reads are classified. The separate 200-sample protein-alignment experiment addresses additional candidate detection, and its NR validation is not required to interpret this completed first-step result.</p>'
body+='<h2>Reproducibility and scope</h2><p>All five arms used the same frozen input subset and per-sample downstream workflow. Location-cluster uncertainty was evaluated across 31 location labels; samples and collection times are correlated. Candidate and final-read outputs, source history, raw evidence and resource summaries are retained privately. No production pipeline or public branch was changed by this report.</p><p>Source and result commits: <code>experiments/amino_acids/history/results/first-step-1000/record.json</code> and <code>experiments/amino_acids/history/results/first-step-exceptions/record.json</code>. The report receipt lists input file hashes.</p>'
(r/'first-step-result.html').write_text(page('First-step amino-acid screen',body))
ids=headers['replicates'][0]['mapped_pair_IDs'];assert len(ids)==8 and headers['only_header_lines_changed'] and headers['alignment_multiset_equal_within_format']
body='<p>A controlled replay of eight outcome-selected read pairs changed human-filter retention when only FASTQ header format changed. Sequences, qualities and record order were identical. Each format was run twice with explicit Bowtie2 seed 0.</p>'+table(['Header format','Example mate 1','Example mate 2','Human-mapped pairs','Retained pairs'],[['Slash mate suffix','@SRR35904031.1024459631/1','@SRR35904031.1024459631/2',8,0],['Space mate comment','@SRR35904031.1024459631 1','@SRR35904031.1024459631 2',0,8]])
body+='<p>The space form exactly matches the native SAM-to-FASTQ roundtrip. Results and alignment multisets were stable within each format across both repeats. Bowtie2 documents read-name-dependent pseudo-random initialization, consistent with this observation. <a href="https://bowtie-bio.sourceforge.net/bowtie2/manual.shtml#randomness-in-bowtie-2">Bowtie2 documentation</a>.</p><h2>Read-pair identifiers</h2><ul>'+''.join('<li><code>'+x+'</code></li>' for x in ids)+'</ul><p>This is a selected mechanism check, not an estimate of population frequency. It does not establish whether the reads are truly human or viral. The original experiment outputs remain unchanged. This note is local and has not been filed as a repository issue; David can decide whether to file it.</p><p>Evidence: <code>results/preparation-discrepancies/header-control-protocol.json</code>, <code>header-control-summary.json</code>, and <code>experiments/amino_acids/history/results/read-header-effect/record.json</code>.</p>'
(r/'bowtie-header-note.html').write_text(page('Bowtie2 header reproducibility',body))
receipt=dict(created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),completed_result=True,independent_of_pending_NR=True,inputs=[dict(path=name,bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for name,p in paths.items()],outputs=[dict(file=n,sha256=hashlib.sha256((r/n).read_bytes()).hexdigest()) for n in ['first-step-result.html','bowtie-header-note.html']]);(r/'first-step-report-receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(dict(union_gain_pct=100*19637/baseline,union_to_NT20_CPU_ratio=ratio,outputs=['first-step-result.html','bowtie-header-note.html'])))
